parameters.functionCode:
const crypto = require('crypto');

const secret = $env.LINE_CHANNEL_SECRET;
if (!secret) {
  throw new Error('Missing env LINE_CHANNEL_SECRET');
}

const headers = $json.headers || {};
const signature = headers['x-line-signature'] || headers['X-Line-Signature'];
if (!signature) {
  item.json = { ok: false, error: 'Missing X-Line-Signature header' };
  return [item];
}

// Raw body は Webhookノードのオプション rawBody=true で出力に含める（キー名はrawBody）
const rawBody = $json.rawBody ?? $json.bodyRaw ?? $json.bodyString ?? (typeof $json.body === 'string' ? $json.body : JSON.stringify($json.body));
if (!rawBody) {
  throw new Error('Missing raw body for signature validation');
}

const digest = crypto.createHmac('sha256', secret).update(rawBody).digest('base64');
item.json.isValid = (digest === signature);
return [item];

